def feature(s):
    if not s:
        return 0.0
    v = s.get('volume_per_atom_A3')
    if v is None or v <= 0:
        return 0.0
    props = s.get('element_properties') or {}
    comp = s.get('composition') or {}
    total = 0.0
    weight = 0.0
    for el, x in comp.items():
        r = (props.get(el) or {}).get('covalent_radius_A')
        if x is not None and x > 0 and r is not None and r > 0:
            total += x * r * r * r
            weight += x
    if weight <= 0:
        return 0.0
    return float(4.0 * pi * total / (3.0 * weight * v))

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    radii = [(props.get(a.get('element')) or {}).get('covalent_radius_A') or 0.0 for a in sites]
    best = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i')
        j = edge.get('j')
        d = edge.get('distance_A') or 0.0
        if i is None or j is None or i < 0 or j < 0 or i >= len(sites) or j >= len(sites) or d <= 0:
            continue
        if radii[i] <= 0 or radii[j] <= 0:
            continue
        x = d / (radii[i] + radii[j])
        if best == 0 or x < best:
            best = x
    return float(best)

