def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    if n == 0:
        return 0.0
    nearest = [0.0 for a in sites]
    edges = s.get('neighbors') or []
    for edge in edges:
        i = edge.get('i')
        d = edge.get('distance_A') or 0.0
        if i is not None and 0 <= i < n and d > 0:
            if nearest[i] == 0 or d < nearest[i]:
                nearest[i] = d
    counts = [0.0 for a in sites]
    for edge in edges:
        i = edge.get('i')
        j = edge.get('j')
        d = edge.get('distance_A') or 0.0
        if i is None or j is None or i < 0 or j < 0 or i >= n or j >= n or d <= 0:
            continue
        if nearest[i] > 0 and d <= 1.6 * nearest[i]:
            occ = sites[j].get('occupancy')
            occ = 1.0 if occ is None else max(0.0, occ)
            counts[i] += occ * exp(1.0 - (d / nearest[i]) ** 6)
    return float(sum(counts) / n)

