def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    nearest = [0.0 for a in sites]
    edges = s.get('neighbors') or []
    for edge in edges:
        i = edge.get('i')
        d = edge.get('distance_A') or 0.0
        if i is not None and 0 <= i < n and d > 0:
            if nearest[i] == 0 or d < nearest[i]:
                nearest[i] = d
    counts = [0.0 for a in sites]
    sums = [0.0 for a in sites]
    squares = [0.0 for a in sites]
    for edge in edges:
        i = edge.get('i')
        d = edge.get('distance_A') or 0.0
        if i is not None and 0 <= i < n and d > 0 and nearest[i] > 0 and d <= 1.3 * nearest[i]:
            counts[i] += 1.0
            sums[i] += d
            squares[i] += d * d
    total = 0.0
    valid = 0
    for i in range(n):
        if counts[i] > 0 and sums[i] > 0:
            total += max(0.0, counts[i] * squares[i] / (sums[i] * sums[i]) - 1.0)
            valid += 1
    return float(total / valid) if valid else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    radii = [(props.get(a.get('element')) or {}).get('covalent_radius_A') or 0.0 for a in sites]
    en = [(props.get(a.get('element')) or {}).get('eneg') for a in sites]
    amount = sum(1.0 if a.get('occupancy') is None else max(0.0, a.get('occupancy')) for a in sites)
    if amount <= 0:
        return 0.0
    total = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i')
        j = edge.get('j')
        d = edge.get('distance_A') or 0.0
        if i is None or j is None or i < 0 or j < 0 or i >= len(sites) or j >= len(sites) or d <= 0:
            continue
        if radii[i] <= 0 or radii[j] <= 0 or en[i] is None or en[j] is None:
            continue
        w = max(0.0, 1.35 - d / (radii[i] + radii[j])) ** 2
        oi = sites[i].get('occupancy')
        oj = sites[j].get('occupancy')
        w *= (1.0 if oi is None else max(0.0, oi)) * (1.0 if oj is None else max(0.0, oj))
        total += w * (en[i] - en[j]) ** 2 / d
    return float(total / (2.0 * amount))

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    radii = [(props.get(a.get('element')) or {}).get('covalent_radius_A') or 0.0 for a in sites]
    en = [(props.get(a.get('element')) or {}).get('eneg') for a in sites]
    counts = [0.0 for a in sites]
    for edge in s.get('neighbors') or []:
        i = edge.get('i')
        j = edge.get('j')
        d = edge.get('distance_A') or 0.0
        if i is None or j is None or i < 0 or j < 0 or i >= len(sites) or j >= len(sites) or d <= 0:
            continue
        if radii[i] > 0 and radii[j] > 0 and d <= 1.25 * (radii[i] + radii[j]):
            occ = sites[j].get('occupancy')
            counts[i] += 1.0 if occ is None else max(0.0, occ)
    total = 0.0
    weight = 0.0
    for i in range(len(sites)):
        if en[i] is not None and en[i] >= 2.5 and radii[i] > 0:
            occ = sites[i].get('occupancy')
            w = 1.0 if occ is None else max(0.0, occ)
            total += w * counts[i]
            weight += w
    return float(total / weight) if weight > 0 else 0.0

def feature(s):
    if not s:
