        return 0.0
    props = s.get('element_properties') or {}
    total = 0.0
    weight = 0.0
    for el, x in (s.get('composition') or {}).items():
        valence = (props.get(el) or {}).get('valence_electrons')
        if x is not None and x > 0 and valence is not None:
            total += x * valence
            weight += x
    return float(total / (weight * v)) if weight > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    radii = [(props.get(a.get('element')) or {}).get('covalent_radius_A') or 0.0 for a in sites]
    hist = [{} for a in sites]
    weights = [0.0 for a in sites]
    for edge in s.get('neighbors') or []:
        i = edge.get('i')
        j = edge.get('j')
        d = edge.get('distance_A') or 0.0
        if i is None or j is None or i < 0 or j < 0 or i >= len(sites) or j >= len(sites) or d <= 0:
            continue
        if radii[i] <= 0 or radii[j] <= 0:
            continue
        w = max(0.0, 1.35 - d / (radii[i] + radii[j])) ** 2
        occ = sites[j].get('occupancy')
        w *= 1.0 if occ is None else max(0.0, occ)
        if w > 0:
            el = sites[j].get('element')
            hist[i][el] = hist[i].get(el, 0.0) + w
            weights[i] += w
    total = 0.0
    valid = 0
    for i in range(len(sites)):
        if weights[i] > 0:
            for w in hist[i].values():
                p = w / weights[i]
                total -= p * log(p)
            valid += 1
    return float(total / valid) if valid else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    nearest = [0.0 for a in sites]
    second = [0.0 for a in sites]
    edges = s.get('neighbors') or []
    for edge in edges:
        i = edge.get('i')
        d = edge.get('distance_A') or 0.0
        if i is not None and 0 <= i < len(sites) and d > 0:
            if nearest[i] == 0 or d < nearest[i]:
                nearest[i] = d
    for edge in edges:
        i = edge.get('i')
        d = edge.get('distance_A') or 0.0
        if i is not None and 0 <= i < len(sites) and nearest[i] > 0 and d > 1.15 * nearest[i]:
            if second[i] == 0 or d < second[i]:
                second[i] = d
    values = [second[i] / nearest[i] - 1.0 for i in range(len(sites)) if nearest[i] > 0 and second[i] > 0]
    return float(sum(values) / len(values)) if values else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    occupancies = [1.0 if a.get('occupancy') is None else max(0.0, a.get('occupancy')) for a in sites]
    amount = sum(occupancies)
    if amount <= 0:
        return 0.0
    total = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i')
        j = edge.get('j')
        d = edge.get('distance_A') or 0.0
        if i is not None and j is not None and 0 <= i < len(sites) and 0 <= j < len(sites) and d > 0:
            total += occupancies[i] * occupancies[j] * exp(-d / 2.0)
    return float(total / amount)
